import React, { useState, useEffect } from 'react';
import { 
  BarChart3, TrendingUp, TrendingDown, MoreVertical,
  DollarSign, ShoppingCart, Target, RefreshCw
} from 'lucide-react';

const SalesChart = ({ timeRange }) => {
  const [chartData, setChartData] = useState([]);
  const [selectedMetric, setSelectedMetric] = useState('revenue');

  useEffect(() => {
    // Données simulées selon la période
    const data = {
      jour: [45, 52, 38, 65, 72, 88, 95, 102, 88, 76, 65, 72],
      semaine: [1200, 1350, 980, 1560, 1780, 1980, 2100],
      mois: [4500, 5200, 3800, 6500, 7200, 8800, 9500, 10200, 8800, 7600, 6500, 7200],
      année: [45000, 52000, 38000, 65000, 72000, 88000, 95000, 102000, 88000, 76000, 65000, 72000]
    };

    setChartData(data[timeRange] || data.mois);
  }, [timeRange]);

  const maxValue = Math.max(...chartData);
  const total = chartData.reduce((a, b) => a + b, 0);
  const average = total / chartData.length;
  const growth = 15.7; // Pourcentage de croissance

  const metrics = [
    { id: 'revenue', label: 'Revenu', value: '€' + total.toLocaleString(), icon: <DollarSign className="h-4 w-4" />, change: '+15.7%' },
    { id: 'orders', label: 'Commandes', value: chartData.length * 12, icon: <ShoppingCart className="h-4 w-4" />, change: '+8.2%' },
    { id: 'target', label: 'Objectif', value: '125%', icon: <Target className="h-4 w-4" />, change: '+25%' }
  ];

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6 h-full">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-6">
        <div>
          <h3 className="text-lg font-bold text-neutral-900 dark:text-white mb-2">Performance des ventes</h3>
          <div className="flex items-center space-x-2">
            <div className="flex items-center text-green-500">
              <TrendingUp className="h-4 w-4 mr-1" />
              <span className="text-sm font-medium">{growth}% cette période</span>
            </div>
            <span className="text-xs text-neutral-500 dark:text-neutral-500 px-2 py-1 bg-neutral-100 dark:bg-neutral-800 rounded-full">
              {timeRange}
            </span>
          </div>
        </div>
        <div className="flex items-center space-x-2 mt-3 sm:mt-0">
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-colors">
            <RefreshCw className="h-4 w-4 text-neutral-600 dark:text-neutral-400" />
          </button>
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-colors">
            <MoreVertical className="h-4 w-4 text-neutral-600 dark:text-neutral-400" />
          </button>
        </div>
      </div>

      {/* Metrics */}
      <div className="grid grid-cols-3 gap-4 mb-6">
        {metrics.map((metric) => (
          <div 
            key={metric.id}
            className={`p-4 rounded-2xl transition-all duration-300 cursor-pointer hover:scale-105 ${
              selectedMetric === metric.id
                ? 'bg-gradient-to-r from-primary-50 to-primary-100/50 dark:from-primary-900/30 dark:to-primary-800/20 border-l-4 border-primary-500'
                : 'bg-neutral-50 dark:bg-neutral-800/50'
            }`}
            onClick={() => setSelectedMetric(metric.id)}
          >
            <div className="flex items-center justify-between mb-2">
              <div className="h-8 w-8 rounded-lg bg-primary-500/10 flex items-center justify-center">
                {metric.icon}
              </div>
              <span className="text-xs font-medium text-green-500 bg-green-500/10 px-2 py-1 rounded-full">
                {metric.change}
              </span>
            </div>
            <p className="text-2xl font-bold text-neutral-900 dark:text-white">{metric.value}</p>
            <p className="text-xs text-neutral-600 dark:text-neutral-400">{metric.label}</p>
          </div>
        ))}
      </div>

      {/* Chart */}
      <div className="relative h-56">
        <div className="absolute inset-0 flex items-end space-x-1 px-2">
          {chartData.map((value, index) => {
            const height = (value / maxValue) * 100;
            const isPeak = value === maxValue;

            return (
              <div 
                key={index}
                className="relative flex-1 group"
              >
                <div
                  className={`
                    rounded-t-lg transition-all duration-500 ease-out
                    ${isPeak 
                      ? 'bg-gradient-to-t from-primary-500 to-secondary-500' 
                      : 'bg-gradient-to-t from-primary-400/80 to-primary-300/80'
                    }
                    group-hover:opacity-90
                  `}
                  style={{ height: `${height}%` }}
                >
                  <div className="absolute -top-8 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                    <div className="px-2 py-1 bg-neutral-900 dark:bg-neutral-800 text-white text-xs rounded-lg whitespace-nowrap">
                      €{value.toLocaleString()}
                    </div>
                  </div>
                </div>
                <div className="text-center mt-2">
                  <span className="text-xs text-neutral-500 dark:text-neutral-500">
                    {timeRange === 'jour' ? index + 8 + 'h' : 
                     timeRange === 'semaine' ? ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'][index] :
                     timeRange === 'mois' ? index + 1 + ' jan' :
                     ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Juin', 'Juil', 'Aoû', 'Sep', 'Oct', 'Nov', 'Déc'][index]}
                  </span>
                </div>
              </div>
            );
          })}
        </div>

        {/* Grid lines */}
        <div className="absolute inset-0 pointer-events-none">
          {[...Array(5)].map((_, i) => (
            <div 
              key={i}
              className="absolute left-0 right-0 border-t border-neutral-200 dark:border-neutral-800/50"
              style={{ bottom: `${i * 25}%` }}
            >
              <span className="absolute -left-8 -translate-y-1/2 text-xs text-neutral-500">
                {Math.round((maxValue / 4) * (4 - i)).toLocaleString()}€
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* Legend */}
      <div className="flex items-center justify-center space-x-6 mt-6 pt-6 border-t border-neutral-200 dark:border-neutral-800">
        <div className="flex items-center space-x-2">
          <div className="h-3 w-3 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500"></div>
          <span className="text-sm text-neutral-600 dark:text-neutral-400">Ventes réelles</span>
        </div>
        <div className="flex items-center space-x-2">
          <div className="h-3 w-3 rounded-full bg-gradient-to-r from-primary-400/50 to-secondary-400/50"></div>
          <span className="text-sm text-neutral-600 dark:text-neutral-400">Prévision</span>
        </div>
      </div>
    </div>
  );
};

export default SalesChart;
